// Build Apify Queries v3 — AI-first, keyword-table fallback
// AI - Parse Target Description runs first and extracts search_terms + search_location
const data = $('Store Inputs').first().json;
const totalCount = data.count || 50;
const explicitLocation = (data.location || '').trim();
const desc = (data.target_description || '').trim();

// ── READ AI OUTPUT ────────────────────────────────────────────────────────────
let aiTerms = [];
let aiLocation = '';
try {
  const aiOutput = $input.first().json.output || {};
  if (aiOutput.search_terms) {
    aiTerms = String(aiOutput.search_terms).split(',').map(s => s.trim()).filter(Boolean);
  }
  if (aiOutput.search_location) {
    aiLocation = String(aiOutput.search_location).trim();
  }
} catch(e) { /* AI output unavailable, use fallback */ }

let queries = null;
let searchLocation = explicitLocation || aiLocation || 'United States';

// ── PRIMARY: AI-extracted search terms (when user wrote a description) ────────
if (desc.length > 0 && aiTerms.length > 0) {
  queries = aiTerms;
}

// ── FALLBACK: TYPE_VARIATIONS keyword table ───────────────────────────────────
if (!queries || queries.length === 0) {
  const vertical = data.b2b_vertical || '';
  const industry = (data.industry || '').trim();
  const sub = JSON.parse(data.insurance_sub_targets || '[]');
  const extraKeywords = JSON.parse(data.keywords || '[]');
  const d = (desc || industry).toLowerCase();

  const TYPE_VARIATIONS = {
    'medspa':           ['medspa', 'med spa', 'medical spa', 'aesthetic clinic', 'laser spa', 'beauty clinic'],
    'med spa':          ['med spa', 'medspa', 'medical spa', 'aesthetic clinic', 'laser spa'],
    'medical spa':      ['medical spa', 'medspa', 'med spa', 'aesthetic clinic', 'laser clinic'],
    'botox':            ['botox clinic', 'cosmetic injections', 'medical aesthetics', 'medspa'],
    'coolsculpting':    ['coolsculpting', 'body contouring', 'fat reduction clinic', 'medspa'],
    'chiropractor':     ['chiropractor', 'chiropractic clinic', 'chiropractic office', 'back pain clinic'],
    'dentist':          ['dentist', 'dental office', 'dental clinic', 'cosmetic dentist', 'family dentist'],
    'dental':           ['dental office', 'dentist', 'dental clinic', 'orthodontist', 'dental practice'],
    'hvac':             ['HVAC contractor', 'air conditioning repair', 'heating and cooling', 'AC repair', 'HVAC company'],
    'plumber':          ['plumber', 'plumbing company', 'plumbing contractor', 'drain service'],
    'plumbing':         ['plumbing company', 'plumber', 'plumbing contractor', 'drain cleaning'],
    'roofing':          ['roofing contractor', 'roofer', 'roofing company', 'roof repair'],
    'landscaping':      ['landscaping company', 'lawn care', 'landscape contractor', 'garden services'],
    'marketing agency': ['marketing agency', 'digital marketing agency', 'social media agency', 'advertising agency', 'SEO agency'],
    'marketing':        ['marketing agency', 'digital marketing agency', 'social media marketing', 'advertising agency'],
    'real estate':      ['real estate agent', 'real estate broker', 'realtor', 'property management'],
    'gym':              ['gym', 'fitness center', 'fitness studio', 'health club', 'crossfit gym'],
    'fitness':          ['fitness center', 'gym', 'personal trainer', 'fitness studio', 'health club'],
    'salon':            ['hair salon', 'beauty salon', 'nail salon', 'barbershop', 'hair studio'],
    'spa':              ['day spa', 'spa', 'wellness spa', 'massage therapy', 'relaxation spa'],
    'lawyer':           ['attorney', 'law firm', 'legal services', 'lawyer', 'law office'],
    'attorney':         ['attorney', 'law firm', 'legal services', 'lawyer'],
    'accountant':       ['accountant', 'CPA', 'accounting firm', 'tax preparation', 'bookkeeping'],
    'insurance':        ['insurance agency', 'insurance broker', 'insurance agent', 'commercial insurance'],
    'contractor':       ['general contractor', 'construction company', 'remodeling contractor', 'home contractor'],
    'construction':     ['general contractor', 'construction company', 'building contractor', 'commercial construction'],
    'cleaning':         ['cleaning service', 'house cleaning', 'commercial cleaning', 'janitorial service'],
    'restaurant':       ['restaurant', 'dining', 'cafe', 'eatery', 'bistro'],
    'staffing':         ['staffing agency', 'temp agency', 'recruiting firm', 'employment agency'],
    'recruiting':       ['recruiting firm', 'staffing agency', 'executive search', 'headhunter'],
    'software':         ['software company', 'SaaS company', 'tech startup', 'software development'],
    'saas':             ['SaaS company', 'software company', 'cloud software', 'B2B software'],
    'physical therapy': ['physical therapy', 'PT clinic', 'rehabilitation center', 'sports medicine clinic'],
    'chiropractic':     ['chiropractic clinic', 'chiropractor', 'chiropractic office', 'back pain specialist'],
    'mortgage':         ['mortgage broker', 'mortgage lender', 'home loan', 'mortgage company'],
    'financial':        ['financial advisor', 'financial planner', 'wealth management', 'investment advisor'],
    'photography':      ['photographer', 'photography studio', 'wedding photographer', 'commercial photography'],
    'trucking':         ['trucking company', 'freight company', 'logistics company', 'transportation company'],
    'pest control':     ['pest control', 'exterminator', 'pest management', 'termite control']
  };

  const sortedKeys = Object.keys(TYPE_VARIATIONS).sort((a, b) => b.length - a.length);
  for (const key of sortedKeys) {
    if (d.includes(key)) {
      queries = [...TYPE_VARIATIONS[key]];
      break;
    }
  }

  if (!queries || queries.length === 0) {
    const VERTICAL_QUERIES = {
      marketing_agency:    ['marketing agency', 'digital marketing agency', 'social media agency', 'advertising agency', 'SEO agency', 'PPC agency'],
      saas_software:       ['SaaS company', 'software company', 'tech startup', 'software development company', 'B2B software'],
      business_consultant: ['business consultant', 'management consultant', 'business coach', 'strategy consultant'],
      commercial_support:  ['commercial cleaning', 'janitorial services', 'facility management', 'commercial landscaping'],
      recruiting_firm:     ['staffing agency', 'recruiting firm', 'executive search firm', 'talent acquisition'],
      insurance_agency:    ['insurance agency', 'insurance broker', 'commercial insurance', 'business insurance']
    };
    queries = VERTICAL_QUERIES[vertical] || [industry || 'local business'];

    if (vertical === 'insurance_agency' && sub.length > 0) {
      queries = [];
      if (sub.includes('construction'))  queries.push('general contractor', 'construction company', 'roofing contractor', 'electrical contractor');
      if (sub.includes('medical'))       queries.push('medical office', 'dental office', 'healthcare clinic', 'physical therapy clinic');
      if (sub.includes('manufacturing')) queries.push('manufacturing company', 'industrial manufacturer', 'metal fabrication');
    }
  }

  if (extraKeywords.length > 0) {
    queries = [...new Set([...queries, ...extraKeywords])];
  }

  // Extract location from description text if AI didn't catch it
  if (!searchLocation || searchLocation === 'United States') {
    const locMatch = desc.match(/\bin\s+([A-Z][A-Za-z\s]+?)(?:\s*,\s*[A-Z]{2})?(?=\s*(?:who|that|with|needing|$))/i);
    if (locMatch && locMatch[1] && locMatch[1].trim().length < 50) {
      searchLocation = locMatch[1].trim();
    }
  }
}

queries = (queries || ['local business']).slice(0, 6);
const perQueryLimit = Math.max(20, Math.ceil(totalCount / queries.length));

return [{
  json: {
    ...data,
    apify_queries: queries,
    apify_location: searchLocation,
    per_query_limit: perQueryLimit,
    search_label: `${desc || data.b2b_vertical || data.industry} | ${searchLocation}`,
    query_source: (desc.length > 0 && aiTerms.length > 0) ? 'ai' : 'keyword_table'
  }
}];

// Normalize Apify Google Places results into consistent business objects
const items = $input.all();
const inputs = $('Store Inputs').first().json;

const businesses = [];

for (const item of items) {
  const place = item.json;

  if (!place.title && !place.name) continue;

  const name = place.title || place.name || 'Unknown Business';
  const website = place.website || place.url || null;
  const email = place.emailAddress || place.email || null;
  const phone = place.phoneNumber || place.phone || null;
  const address = place.address || place.location?.address || null;
  const rating = place.totalScore || place.rating || null;
  const reviews = place.reviewsCount || place.reviewCount || place.userRatingsTotal || 0;
  const category = (place.categories && place.categories[0]) || place.primaryType || inputs.b2b_vertical || null;

  businesses.push({
    name,
    website,
    email,
    phone,
    address,
    rating: rating ? parseFloat(rating) : null,
    reviews: parseInt(reviews) || 0,
    category,
    industry: inputs.industry || inputs.b2b_vertical,
    service: inputs.client_service || inputs.industry || inputs.b2b_vertical,
    location: inputs.location,
    raw_data: JSON.stringify(place).substring(0, 500)
  });
}

if (businesses.length === 0) {
  return [{ json: { __empty: true, reason: 'No businesses found in Apify response' } }];
}

return businesses.map(b => ({ json: b }));

