const crypto = require('crypto');
const secret = $env.N8N_HMAC_SECRET || 'dev-secret';
const inputs = $('Store Inputs').first().json;

const businesses = $input.first().json.data || [];

const callbackBody = {
  run_id: inputs.run_id,
  workflow_type: 'prospect_discovery',
  status: 'complete',
  org_id: inputs.org_id,
  output: {
    businesses_found: businesses.length,
    vertical: inputs.b2b_vertical,
    location: inputs.location,
    min_score_applied: inputs.min_score
  }
};

const payload = JSON.stringify(callbackBody);
const signature = crypto.createHmac('sha256', secret).update(payload).digest('hex');

return [{ json: {
  callback_url: inputs.callback_url,
  payload,
  signature
} }];
